'use strict';
// Each exchange is a small sequence of clearly attributed, readable beats.
let dialogueFlow=null;
const DIALOGUE_CAST={Sarah:['Sarah Maria','sarah'],'Sarah Maria':['Sarah Maria','sarah'],Antonella:['Queen Antonella','queen-warm'],'Queen Antonella':['Queen Antonella','queen-warm'],'King Daddy':['King Daddy','daddy-proud'],Nessie:['Nessie','nessie.png'],'Frog DJ':['Frog DJ','frog'],Lola:['Lola the Lizard','lola'],Fifi:['Fifi the Flamingo','fifi']};
function dialogueBeats(text,speaker,portrait){const beats=[];let who=speaker,key=portrait;for(const raw of text.replace(/\s+(Sarah Maria|Sarah|Antonella|Queen Antonella|King Daddy|Nessie|Frog DJ|Lola|Fifi):/g,'\n$1:').split('\n')){const line=raw.trim();if(!line)continue;const match=line.match(/^([^:]+):\s*(.*)$/);if(match&&DIALOGUE_CAST[match[1]]){[who,key]=DIALOGUE_CAST[match[1]];beats.push({speaker:who,portrait:key,text:match[2]});}else if(line.startsWith('(')){beats.push({speaker:'A little moment',portrait:key,text:line.slice(1).replace(/\)$/,'')});}else{const last=beats[beats.length-1];if(last&&last.speaker===who)last.text+=' '+line;else beats.push({speaker:who,portrait:key,text:line});}}return beats;}
function startConversation(id,after){const c=conversations[id];if(mode!=='sarah'||dialogueSeen.has(id)||!c)return false;activeDialogueId=id;dialogueSeen.add(id);dialogueAfter=after;dialogueChoiceIndex=0;state='dialogue';keys.clear();dialogueFlow={id,beats:dialogueBeats(c.line,c.speaker,c.portrait),index:0,phase:'opening'};const panel=$('dialogue-panel');panel.style.display='flex';panel.dataset.scene=isTraining()?'training':isPalace()?'palace':'lagoon';document.querySelector('.game-shell')?.classList.add('conversation-active');$('dialogue-response').style.display='none';$('sarah-reply-avatar').style.display='none';$('dialogue-hint').style.display='none';$('dialogue-close').onclick=finishDialogue;$('dialogue-next').onclick=advanceConversation;showConversationBeat();return true;}
function showConversationBeat(){if(!dialogueFlow)return;const flow=dialogueFlow,beat=flow.beats[flow.index],c=conversations[flow.id];$('dialogue-speaker').textContent=beat.speaker;$('dialogue-line').textContent=beat.text;renderSpeechAvatar(beat.portrait,beat.speaker,$('dialogue-portrait'));$('dialogue-panel').dataset.speaker=beat.portrait;$('dialogue-kicker').textContent=flow.phase==='response'?'A LITTLE CONVERSATION':isTraining()?'THE TRAINING LAGOON':isPalace()?'THE PEARL PALACE':'ALONG THE ADVENTURE';$('dialogue-page').textContent=flow.beats.length>1?(flow.index+1)+' / '+flow.beats.length:'';
 const choices=flow.phase==='opening'&&flow.index===flow.beats.length-1;const options=$('dialogue-options');options.innerHTML='';options.style.display=choices?'flex':'none';$('dialogue-next').style.display=choices?'none':'inline-flex';$('dialogue-next').textContent=flow.phase==='response'&&flow.index===flow.beats.length-1?'Keep swimming':'Continue';
 if(choices){flow.phase='choices';c.options.forEach(([reply,response],i)=>{const b=document.createElement('button');b.className='dialogue-option';b.textContent=reply;b.dataset.choice=String(i+1);b.onfocus=()=>{dialogueChoiceIndex=i;};b.onclick=()=>chooseConversationReply(i);options.appendChild(b);});options.querySelector('button')?.focus();}else $('dialogue-next').focus();
}
function chooseConversationReply(index){if(!dialogueFlow||dialogueFlow.phase!=='choices')return;const c=conversations[dialogueFlow.id],option=c.options[index];if(!option)return;keys.clear();dialogueChoiceIndex=index;dialogueFlow.beats=[{speaker:'Sarah Maria',portrait:'sarah',text:option[0]},...dialogueBeats(option[1],c.speaker,c.portrait)];dialogueFlow.index=0;dialogueFlow.phase='response';showConversationBeat();}
function advanceConversation(){if(!dialogueFlow)return;if(dialogueFlow.phase==='choices')return;dialogueFlow.index++;if(dialogueFlow.index>=dialogueFlow.beats.length){finishDialogue();return;}showConversationBeat();}
function handleConversationKey(e){if(state!=='dialogue')return false;const key=e.key;if(['Enter',' ','Escape','ArrowDown','ArrowUp','ArrowLeft','ArrowRight','Tab'].includes(key))e.preventDefault();if(key==='Escape'){finishDialogue();return true;}if(e.repeat)return true;if(key==='Tab'){const buttons=dialogueFlow?.phase==='choices'?Array.from($('dialogue-options').querySelectorAll('button')):[$('dialogue-next')];buttons.push($('dialogue-close'));const current=buttons.indexOf(document.activeElement),next=(current+(e.shiftKey?-1:1)+buttons.length)%buttons.length;buttons[next]?.focus();return true;}
 if(dialogueFlow?.phase==='choices'){const options=conversations[activeDialogueId].options;if(['1','2','3'].includes(key))chooseConversationReply(Number(key)-1);else if(key==='Enter'||key===' '){if(document.activeElement===$('dialogue-close'))finishDialogue();else chooseConversationReply(dialogueChoiceIndex);}else if(key.startsWith('Arrow')){dialogueChoiceIndex=clamp(dialogueChoiceIndex+(['ArrowUp','ArrowLeft'].includes(key)?-1:1),0,options.length-1);$('dialogue-options').querySelectorAll('button')[dialogueChoiceIndex]?.focus();}}else if(key==='Enter'||key===' '){if(document.activeElement===$('dialogue-close'))finishDialogue();else advanceConversation();}return true;}
